# Illustrative example, spec version v0.2. Decoded view; hashes and signatures shortened.
# checkout_jwt: a JWT signed by the merchant. AP2 does not define the payload;
# it comes from the commerce protocol (a UCP Checkout object when AP2 runs inside UCP).
{
  "header": {
    "alg": "ES256",
    "typ": "JWT",
    "kid": "merchant-key-1"
  },
  "payload": "<Checkout object from the commerce protocol>",
  "signature": "MEUCIQ..."
}

# Illustrative example, spec version v0.2. Decoded view; hashes and signatures shortened.
# The outer keys (..._mandate_content) are labels for this page, not AP2 fields; each inner object is one Mandate Content payload.
{
  "checkout_mandate_content": {
    "vct": "mandate.checkout.1",
    "checkout_jwt": "eyJhbGciOiJFUzI1NiIs...",
    "checkout_hash": "Nv3Wq...X8"
  },
  "payment_mandate_content": {
    "vct": "mandate.payment.1",
    "transaction_id": "Nv3Wq...X8",
    "payee": {
      "id": "merchant_1",
      "name": "Example Outdoor Store",
      "website": "https://outdoor.example"
    },
    "payment_amount": {
      "amount": 27999,
      "currency": "USD"
    },
    "payment_instrument": {
      "id": "pi_7f3c",
      "type": "card",
      "description": "Card ending 4242"
    }
  }
}

# Illustrative example, spec version v0.2. Decoded view; hashes and signatures shortened.
# Closed Payment Mandate as an SD-JWT signed with user_sk (Trusted Surface).
# transaction_id equals checkout_hash: both are the hash of checkout_jwt.
{
  "header": {
    "alg": "ES256",
    "typ": "kb+sd-jwt"
  },
  "payload": {
    "delegate_payload": [
      {
        "...": "G2Du...TgM"
      }
    ],
    "iat": 1791720000,
    "aud": "credential-provider",
    "nonce": "a8b7c6d5",
    "sd_hash": "uixo...0Ck",
    "_sd_alg": "sha-256"
  },
  "disclosures": [
    [
      "FW6M...Idw",
      {
        "vct": "mandate.payment.1",
        "transaction_id": "Nv3Wq...X8",
        "payee": {
          "id": "merchant_1",
          "name": "Example Outdoor Store"
        },
        "payment_amount": {
          "amount": 27999,
          "currency": "USD"
        },
        "payment_instrument": {
          "id": "pi_7f3c",
          "type": "card",
          "description": "Card ending 4242"
        }
      }
    ]
  ]
}

# Illustrative example, spec version v0.2. Decoded view; hashes and signatures shortened.
# Closed Checkout Mandate sent to the merchant with the payment token.
{
  "header": {
    "alg": "ES256",
    "typ": "kb+sd-jwt"
  },
  "payload": {
    "delegate_payload": [
      {
        "...": "7VLY...y34"
      }
    ],
    "iat": 1791720010,
    "aud": "merchant",
    "nonce": "b9c8d7e6",
    "sd_hash": "FzLo...JN8",
    "_sd_alg": "sha-256"
  },
  "disclosures": [
    [
      "w-n1...Wow",
      "checkout_jwt",
      "eyJhbGciOiJFUzI1NiIs..."
    ],
    [
      "szhp...Sw",
      {
        "_sd": [
          "3A9U...FFM"
        ],
        "vct": "mandate.checkout.1",
        "checkout_hash": "Nv3Wq...X8"
      }
    ]
  ]
}
